import { build } from 'esbuild';
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, relative, resolve, sep } from 'node:path';
import { createHash } from 'node:crypto';

const root = process.cwd();
const outdir = resolve(root, '.tools/perf-v077');
mkdirSync(outdir, { recursive: true });
const test = resolve(root, 'tests/unit/battle.test.ts');
const baseline = '8364bf1';
const oldTest = execFileSync('git', ['show', `${baseline}:tests/unit/battle.test.ts`], { encoding: 'utf8' });
const hash = text => createHash('sha256').update(text.replaceAll('\r\n', '\n')).digest('hex');
const metadata = { baseline, testSourceHash: hash(readFileSync(test, 'utf8')), baselineTestHash: hash(oldTest), sources: {} };
for (const version of ['old', 'current']) {
  const sources = {};
  await build({ entryPoints: [test], outfile: resolve(outdir, `${version}.test.mjs`), bundle: true,
    platform: 'node', format: 'esm', target: 'node22', sourcemap: 'inline', external: ['vitest'],
    plugins: [{ name: 'record-and-freeze-source', setup(build) {
      build.onLoad({ filter: /\.ts$/ }, args => {
        const path = relative(root, args.path).split(sep).join('/');
        if (args.path === test) {
          const contents = readFileSync(test, 'utf8');
          if (contents.split('}, 20000);').length !== 2) throw new Error('Expected the single original stress timeout');
          return { contents: contents.replace('}, 20000);', '}, 60000);'), loader: 'ts' };
        }
        if (!path.startsWith('src/')) return;
        const contents = version === 'old'
          ? execFileSync('git', ['show', `${baseline}:${path}`], { encoding: 'utf8' })
          : readFileSync(args.path, 'utf8');
        sources[path] = hash(contents);
        return { contents, loader: 'ts' };
      });
    } }],
  });
  metadata.sources[version] = sources;
}
writeFileSync(resolve(outdir, 'metadata.json'), JSON.stringify(metadata, null, 2));
for (const version of ['old', 'current']) {
  const snapshot = resolve(outdir, `${version}-modules`);
  for (const path of Object.keys(metadata.sources[version])) {
    const contents = version === 'old'
      ? execFileSync('git', ['show', `${baseline}:${path}`], { encoding: 'utf8' })
      : readFileSync(resolve(root, path), 'utf8');
    if (hash(contents) !== metadata.sources[version][path]) throw new Error(`Source changed while freezing ${path}`);
    const destination = resolve(snapshot, path);
    mkdirSync(dirname(destination), { recursive: true });
    writeFileSync(destination, contents);
  }
  const destination = resolve(snapshot, 'tests/unit/battle.test.ts');
  mkdirSync(dirname(destination), { recursive: true });
  writeFileSync(destination, readFileSync(test, 'utf8').replace('}, 20000);', '}, 60000);'));
}
writeFileSync(resolve(outdir, 'vitest.config.mts'), `export default { test: { include: ['.tools/perf-v077/*.test.mjs', '.tools/perf-v077/*-modules/tests/unit/battle.test.ts'], reporters: ['default'], maxWorkers: 1, fileParallelism: false, testTimeout: 60000 } };\n`);
console.log(JSON.stringify({ output: outdir, identicalTest: metadata.testSourceHash === metadata.baselineTestHash,
  sourceCount: Object.fromEntries(Object.entries(metadata.sources).map(([key, sources]) => [key, Object.keys(sources).length])) }));
